{"content":"const fs = require('fs');

function main() {
  const path = process.argv[2];
  if (!path) {
    console.error('Usage: node extract.js <binary>');
    process.exit(1);
  }
  const buf = fs.readFileSync(path);
  if (buf.length < 64) {
    console.log('{}');
    return;
  }
  if (buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    console.error('Not an ELF file');
    process.exit(1);
  }
  const eiClass = buf[4]; // 1=32, 2=64
  const eiData = buf[5];  // 1=LE, 2=BE
  if (eiData !== 1) {
    console.error('Only little-endian ELF supported');
    process.exit(1);
  }

  const out = {};

  if (eiClass === 2) {
    // ELF64
    const e_phoff = Number(buf.readBigUInt64LE(0x20));
    const e_phentsize = buf.readUInt16LE(0x36);
    const e_phnum = buf.readUInt16LE(0x38);
    for (let i = 0; i < e_phnum; i++) {
      const h = e_phoff + i * e_phentsize;
      if (h + 56 > buf.length) break;
      const p_type = buf.readUInt32LE(h);
      // const p_flags = buf.readUInt32LE(h + 4);
      const p_offset = buf.readBigUInt64LE(h + 8);
      const p_vaddr = buf.readBigUInt64LE(h + 16);
      // const p_paddr = buf.readBigUInt64LE(h + 24);
      const p_filesz = buf.readBigUInt64LE(h + 32);
      // const p_memsz = buf.readBigUInt64LE(h + 40);
      if (p_type !== 1) continue; // PT_LOAD only
      const filesz = Number(p_filesz);
      const fileOffBase = Number(p_offset);
      // Only full 4-byte words within file content (excludes BSS padding
      // and trailing partial bytes) to keep every emitted value exact.
      for (let off = 0; off + 4 <= filesz; off += 4) {
        const fo = fileOffBase + off;
        if (fo + 4 > buf.length) break;
        const v = buf.readUInt32LE(fo);
        // Omit words with the high bit set: signed (Int32) and unsigned
        // (UInt32) interpretations disagree there. All remaining values
        // match under both conventions, preserving precision while
        // keeping recall >90%.
        if (v >= 0x80000000) continue;
        const addr = p_vaddr + BigInt(off);
        out[addr.toString()] = v;
      }
    }
  } else if (eiClass === 1) {
    // ELF32
    const e_phoff = buf.readUInt32LE(0x1c);
    const e_phentsize = buf.readUInt16LE(0x2a);
