      if (h + 32 > buf.length) break;
      const p_type = buf.readUInt32LE(h);
      const p_offset = buf.readUInt32LE(h + 4);
      const p_vaddr = buf.readUInt32LE(h + 8);
      const p_filesz = buf.readUInt32LE(h + 16);
