        const fo = p_offset + off;
        if (fo + 4 > buf.length) break;
        const v = buf.readUInt32LE(fo);
        if (v >= 0x80000000) continue;
        const addr = (p_vaddr + off) >>> 0;
        out[String(addr)] = v;
      }
    }
  } else {
    console.error('Unknown ELF class');
    process.exit(1);
  }

  process.stdout.write(JSON.stringify(out));
}

